def transform(grid):
    R, C = len(grid), len(grid[0])
    cells = {(r, c) for r in range(R) for c in range(C) if grid[r][c] == 8}
    placements = []
    for r in range(R - 1):
        for c in range(C - 1):
            box = {(r, c), (r, c+1), (r+1, c), (r+1, c+1)}
            if box <= cells:
                placements.append((box, 1))
            for missing, color in [((r, c), 2), ((r+1, c), 3), ((r, c+1), 4)]:
                piece = box - {missing}
                if piece <= cells:
                    placements.append((piece, color))

    by_cell = {p: [] for p in cells}
    for piece, color in placements:
        for p in piece:
            by_cell[p].append((piece, color))

    # Prefer square tiles, then the three L orientations.
    for p in by_cell:
        by_cell[p].sort(key=lambda x: (x[1] != 1, x[1]))

    def solve(left):
        if not left:
            return []
        p = min(left)
        for piece, color in by_cell[p]:
            if piece <= left:
                rest = solve(left - piece)
                if rest is not None:
                    return [(piece, color)] + rest
        return None

    tiling = solve(cells)
    out = [[0] * C for _ in range(R)]
    if tiling:
        for piece, color in tiling:
            for r, c in piece:
                out[r][c] = color
    return out
